        ArgumentNullException.ThrowIfNull(input);
        input = input with { ClientToken = input.ClientToken ?? this.idempotencyTokenProvider() };
        return runtime.InvokeAsync(CheckpointDurableExecutionBinding, input, cancellationToken);
    }

